From f5fe44b8a12ceff41b7fc438c3b84dad3a424c1e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:13:26 +0100
Subject: [PATCH] device: refresh IP configs when their properties change

The IPv4 and IPv6 configs stayed cached until the device's config path
changed, so addresses added later to the same object, like SLAAC ones,
never showed up. Now changes on those objects reset the cached configs.

BUG: 477775
---
 src/device.cpp | 38 ++++++++++++++++++++++++++++++++++++++
 src/device_p.h |  5 +++++
 2 files changed, 43 insertions(+)

diff --git a/src/device.cpp b/src/device.cpp
index cde113c..a27b5d3 100644
--- a/src/device.cpp
+++ b/src/device.cpp
@@ -321,20 +321,28 @@ void NetworkManager::DevicePrivate::propertyChanged(const QString &property, con
         Q_EMIT q->ipV4AddressChanged();
     } else if (property == QLatin1String("Ip4Config")) {
         QDBusObjectPath ip4ConfigObjectPathTmp = value.value<QDBusObjectPath>();
+        const QString oldPath = ipV4ConfigPath;
         if (ip4ConfigObjectPathTmp.path().isNull() || ip4ConfigObjectPathTmp.path() == QLatin1String("/")) {
             ipV4ConfigPath.clear();
         } else {
             ipV4ConfigPath = ip4ConfigObjectPathTmp.path();
         }
+        if (oldPath != ipV4ConfigPath) {
+            watchIpConfig(oldPath, ipV4ConfigPath, SLOT(ipV4ConfigPropertiesChanged()));
+        }
         ipV4Config = IpConfig();
         Q_EMIT q->ipV4ConfigChanged();
     } else if (property == QLatin1String("Ip6Config")) {
         QDBusObjectPath ip6ConfigObjectPathTmp = value.value<QDBusObjectPath>();
+        const QString oldPath = ipV6ConfigPath;
         if (ip6ConfigObjectPathTmp.path().isNull() || ip6ConfigObjectPathTmp.path() == QLatin1String("/")) {
             ipV6ConfigPath.clear();
         } else {
             ipV6ConfigPath = ip6ConfigObjectPathTmp.path();
         }
+        if (oldPath != ipV6ConfigPath) {
+            watchIpConfig(oldPath, ipV6ConfigPath, SLOT(ipV6ConfigPropertiesChanged()));
+        }
         ipV6Config = IpConfig();
         Q_EMIT q->ipV6ConfigChanged();
     } else if (property == QLatin1String("IpInterface")) {
@@ -640,6 +648,36 @@ void NetworkManager::DevicePrivate::dbusPropertiesChanged(const QString &interfa
     }
 }

+void NetworkManager::DevicePrivate::watchIpConfig(const QString &oldPath, const QString &newPath, const char *slot)
+{
+    if (!oldPath.isEmpty()) {
+        QDBusConnection::systemBus().disconnect(NetworkManagerPrivate::DBUS_SERVICE,
+                                                oldPath,
+                                                NetworkManagerPrivate::FDO_DBUS_PROPERTIES,
+                                                QLatin1String("PropertiesChanged"),
+                                                this,
+                                                slot);
+    }
+    if (!newPath.isEmpty()) {
+        QDBusConnection::systemBus()
+            .connect(NetworkManagerPrivate::DBUS_SERVICE, newPath, NetworkManagerPrivate::FDO_DBUS_PROPERTIES, QLatin1String("PropertiesChanged"), this, slot);
+    }
+}
+
+void NetworkManager::DevicePrivate::ipV4ConfigPropertiesChanged()
+{
+    Q_Q(Device);
+    ipV4Config = IpConfig();
+    Q_EMIT q->ipV4ConfigChanged();
+}
+
+void NetworkManager::DevicePrivate::ipV6ConfigPropertiesChanged()
+{
+    Q_Q(Device);
+    ipV6Config = IpConfig();
+    Q_EMIT q->ipV6ConfigChanged();
+}
+
 void NetworkManager::DevicePrivate::propertiesChanged(const QVariantMap &properties)
 {
     // qCDebug(NMQT) << Q_FUNC_INFO << properties;
diff --git a/src/device_p.h b/src/device_p.h
index 812ea5f..3bdfade 100644
--- a/src/device_p.h
+++ b/src/device_p.h
@@ -74,10 +74,15 @@ public:
      */
     virtual void propertyChanged(const QString &property, const QVariant &value);

+private:
+    void watchIpConfig(const QString &oldPath, const QString &newPath, const char *slot);
+
 public Q_SLOTS:
     void deviceStateChanged(uint, uint, uint);
     void dbusPropertiesChanged(const QString &interfaceName, const QVariantMap &properties, const QStringList &invalidatedProperties);
     void propertiesChanged(const QVariantMap &properties);
+    void ipV4ConfigPropertiesChanged();
+    void ipV6ConfigPropertiesChanged();
 };

 } // namespace NetworkManager
